function analyzeNetworkScanResult(target, openPorts, scanMethod) {
  let anomalyMessage = "";

  if (openPorts.length > 0 && target == "127.0.0.1") {
    anomalyMessage = `Anomaly detected: Open port ${openPorts[0]}`;
  }

  return anomalyMessage;
}

// Usage
analyzeNetworkScanResult("127.0.0.1", [135, 445], "native-net");
```

This KQL function constructs an anomaly message based on whether any open ports were detected and where the target system is located (e.g., `127.0.0.1` for a single IP address).

